package io.github.mekkiamiri.ratchet.order.application;

/** Fabrique des stratégies de chiffre d'affaires. */
public final class RevenuePolicyFactory {

    private RevenuePolicyFactory() {
    }

    public static RevenuePolicy create(String type) {
        if ("confirmed".equals(type)) {
            return new ConfirmedOrdersRevenuePolicy();
        }
        throw new IllegalArgumentException("Stratégie inconnue : " + type);
    }
